INSERT INTO use_cases (id,title,category,phase,status,business_problem,solution_description,ai_capability,business_area,value_stream,executive_sponsor,funding_status,risks,requestor_name,planview_tracking_number,annual_value_low_m,annual_value_high_m,complexity,time_to_value_low_mo,time_to_value_high_mo,data_sources,value_components,key_assumptions,roi_timeline,prerequisites) VALUES ('61bfbe8c-52bc-48bd-80c7-ed4a824fa279','Outage Detection & Prediction','Distribution','Phase 1','Under Review','Slow detection of outages drives long SAIDI minutes, wasted truck rolls, and customer dissatisfaction. AMI last-gasp signals are not integrated with OMS today.','Integrate AMI last-gasp / power-on events with OMS and SCADA to detect, predict, and pre-stage for outages. Foundational to FLISR and storm response.','Anomaly Detection','Distribution Operations','Distribution',NULL,NULL,NULL,NULL,NULL,30,62,3,9,15,'AMI (last-gasp/power-on), OMS, SCADA, weather, historical outage records','SAIDI reduction via faster detection ($10M); Crew dispatch efficiency ($2.25M); Predictive pre-staging savings ($20M); OMS accuracy improvement ($1.6M)','Current SAIDI of 90 min; Phase 1 reduces by 5 min; 50,000 annual truck rolls; 15% reduction in unnecessary rolls; $100M annual storm restoration costs','9-15 months','AMI + OMS integration; clean GIS network model');
INSERT INTO use_cases (id,title,category,phase,status,business_problem,solution_description,ai_capability,business_area,value_stream,executive_sponsor,funding_status,risks,requestor_name,planview_tracking_number,annual_value_low_m,annual_value_high_m,complexity,time_to_value_low_mo,time_to_value_high_mo,data_sources,value_components,key_assumptions,roi_timeline,prerequisites) VALUES ('6bb4f22e-074f-4100-9acc-ea038549b44d','Fault Location, Isolation, and Service Restoration (FLISR)','Distribution','Phase 1','Under Review','Manual fault location and restoration takes 8+ SAIDI minutes per event and consumes 500,000 crew hours annually.','Use AMI, OMS, GIS, and recloser/switch telemetry to automatically locate, isolate, and restore faults. Direct extension of outage detection.','Optimization','Distribution Operations','Distribution',NULL,NULL,NULL,NULL,NULL,25,52,3,12,18,'AMI, OMS, GIS network model, SCADA (reclosers/switches), fault indicators','SAIDI reduction from automated isolation ($16M); Restoration labor reduction ($8.5M); CSAT penalty avoidance ($3M); Reduced customer compensation claims ($750K)','8 SAIDI min reduced via automated switching vs. manual; 500K annual crew hours on restoration; FLISR effectiveness depends on clean GIS model','12-18 months','Outage Detection & Prediction; clean GIS connectivity model');
INSERT INTO use_cases (id,title,category,phase,status,business_problem,solution_description,ai_capability,business_area,value_stream,executive_sponsor,funding_status,risks,requestor_name,planview_tracking_number,annual_value_low_m,annual_value_high_m,complexity,time_to_value_low_mo,time_to_value_high_mo,data_sources,value_components,key_assumptions,roi_timeline,prerequisites) VALUES ('7e98e7c0-4a49-4e6a-afdd-7811f3105c36','Predictive Maintenance for OH & UG Assets','Distribution','Phase 1','Refinement','200,000 distribution transformers with a 5% annual failure rate drive emergency O&M premiums and customer interruptions.','Combine inspection records, AMI power-quality data, transformer loading, GIS, weather, and failure history to predict failures and shift from reactive to planned maintenance.','Predictive Maintenance','Asset Management','Distribution',NULL,NULL,NULL,NULL,NULL,22,45,3,15,24,'Inspection records, AMI power quality, transformer loading, GIS, weather, failure history','Transformer failure avoidance ($3M); UG cable failure avoidance ($3.75M); Planned vs. emergency maintenance premium ($18M); Transformer life extension ($1.575M)','200K distribution transformers; 5% annual failure rate; $300M/yr distribution O&M budget; 250 UG cable failures/yr, reduce by 50','15-24 months','AMI integration; historical inspection / failure records digitized');
INSERT INTO use_cases (id,title,category,phase,status,business_problem,solution_description,ai_capability,business_area,value_stream,executive_sponsor,funding_status,risks,requestor_name,planview_tracking_number,annual_value_low_m,annual_value_high_m,complexity,time_to_value_low_mo,time_to_value_high_mo,data_sources,value_components,key_assumptions,roi_timeline,prerequisites) VALUES ('e67782aa-04a8-4072-8364-b7b3085cb732','Load Forecasting at Feeder Level','Distribution','Phase 1','Refinement','System-level load forecasts miss feeder-level variation, leading to over-built capital and stalled DER interconnection studies.','Granular AMI-driven load forecasts per feeder, enabling capacity planning, DER readiness, and EV-charging planning. Critical input to hosting capacity analysis.','Forecasting','Distribution Planning','Distribution',NULL,NULL,NULL,NULL,NULL,12,25,3,12,18,'AMI interval data, weather, DER interconnection records, GIS feeder maps, EV charging data','Deferred distribution capital ($9M); EV charging infra optimization ($525K); DER interconnection backlog reduction ($750K); DR targeting efficiency ($1M)','$300M annual distribution capital budget; 3,000 distribution feeders; 500 DER interconnection applications/yr; EV penetration +20%/yr','12-18 months','AMI interval data aggregated by feeder and transformer');
INSERT INTO use_cases (id,title,category,phase,status,business_problem,solution_description,ai_capability,business_area,value_stream,executive_sponsor,funding_status,risks,requestor_name,planview_tracking_number,annual_value_low_m,annual_value_high_m,complexity,time_to_value_low_mo,time_to_value_high_mo,data_sources,value_components,key_assumptions,roi_timeline,prerequisites) VALUES ('03b063f2-6eb4-42fc-a46f-4620dab7bc9e','Grid Reliability Monitoring','Distribution','Phase 1','Approved','Reliability reporting is manual; 15 analysts spend 50% of their time on SAIDI/SAIFI/CAIDI compilation rather than analysis.','Reporting and dashboard layer on top of AMI/SCADA/OMS data. Low incremental complexity once Phase 1 data is in place. Drives regulatory reporting automation and targeted investment.','Other','Regulatory & Reliability','Distribution',NULL,NULL,NULL,NULL,NULL,8,18,2,6,9,'AMI, SCADA, OMS, power quality meters, GIS, reliability indices','Regulatory reporting automation ($2.03M); Targeted capital investment efficiency ($15M); Regulatory penalty avoidance ($2M); JD Power ranking improvement ($1M)','15 analysts at 50% time on manual reliability reporting; reliability benchmarks tied to $1-5M rate case outcomes; 5% efficiency on $300M capital budget','6-9 months','Phase 1 AMI/OMS/SCADA integration');
INSERT INTO use_cases (id,title,category,phase,status,business_problem,solution_description,ai_capability,business_area,value_stream,executive_sponsor,funding_status,risks,requestor_name,planview_tracking_number,annual_value_low_m,annual_value_high_m,complexity,time_to_value_low_mo,time_to_value_high_mo,data_sources,value_components,key_assumptions,roi_timeline,prerequisites) VALUES ('72f157db-6055-4814-948b-556b6722a76d','DER & EV Charging Management','Distribution','Phase 2','Backlog','Uncoordinated DER and EV charging is overloading distribution transformers and forcing expensive capacity upgrades.','Manage bidirectional power flows and EV-charging impacts using AMI, DER telemetry, and feeder models. Enables FERC Order 2222 market participation.','Optimization','Distribution Operations','Distribution',NULL,NULL,NULL,NULL,NULL,30,65,4,18,24,'AMI, DER telemetry, EV charger data, feeder models, weather, interconnection records','Distribution infra deferral ($7M); EV charging infra deferral ($7.5M); Wholesale market value from DER aggregation ($7.3M); Curtailment avoidance ($7.5M); DR revenue ($3.65M)','500 MW total DER installed; 80,000 EVs (10% of 800K residential); 200 transformers at risk without managed charging','18-24 months','Load Forecasting at Feeder Level; DER telemetry feeds');
INSERT INTO use_cases (id,title,category,phase,status,business_problem,solution_description,ai_capability,business_area,value_stream,executive_sponsor,funding_status,risks,requestor_name,planview_tracking_number,annual_value_low_m,annual_value_high_m,complexity,time_to_value_low_mo,time_to_value_high_mo,data_sources,value_components,key_assumptions,roi_timeline,prerequisites) VALUES ('ada2a5ff-2732-4467-9958-642628a02355','Grid Model Clean-up & Connectivity Inference','Distribution','Phase 2','Refinement','15-25% GIS connectivity error rate causes failed work orders, inaccurate outage locations, and FLISR misfires.','Use ML to infer and correct connectivity errors in GIS / network models by reconciling GIS with AMI, SCADA, and as-built records.','Anomaly Detection','GIS & Asset Records','Distribution',NULL,NULL,NULL,NULL,NULL,8,18,3,12,18,'GIS, AMI, SCADA, as-built records, work orders, connectivity models','Outage location accuracy ($3M); FLISR accuracy ($2.5M); DER interconnection accuracy ($625K); Field crew efficiency ($1M); Engineering planning accuracy ($600K)','15-25% GIS connectivity error rate; 500 DER interconnection studies/yr; 10,000 failed work orders/yr from bad connectivity','12-18 months','Phase 1 data quality issues triaged');
INSERT INTO use_cases (id,title,category,phase,status,business_problem,solution_description,ai_capability,business_area,value_stream,executive_sponsor,funding_status,risks,requestor_name,planview_tracking_number,annual_value_low_m,annual_value_high_m,complexity,time_to_value_low_mo,time_to_value_high_mo,data_sources,value_components,key_assumptions,roi_timeline,prerequisites) VALUES ('52d8a835-e224-4b92-a798-6e49fd5c5ecf','Storm Impact Prediction & Crew Pre-Staging','Distribution','Phase 2','Backlog','Major storms cost $100M/yr in restoration; crews are staged reactively rather than predictively.','Predict storm damage by asset vulnerability and weather forecast, pre-stage crews and materials, coordinate mutual aid more efficiently.','Forecasting','Emergency Response','Distribution',NULL,NULL,NULL,NULL,NULL,22,48,3,12,18,'Weather forecasts, historical storm damage, asset vulnerability, GIS, crew/equipment locations','Pre-staged crews faster restoration ($20M); Crew overtime reduction ($9.56M); Pre-staged material savings ($3M); CSAT ($2M); Mutual aid efficiency ($2M)','5 major storms/yr at $100M total restoration cost; pre-staging cuts restoration time 20%; 500 restoration crews; $10M annual mutual aid costs','12-18 months','Outage Detection & Prediction; Grid Reliability Monitoring');
INSERT INTO use_cases (id,title,category,phase,status,business_problem,solution_description,ai_capability,business_area,value_stream,executive_sponsor,funding_status,risks,requestor_name,planview_tracking_number,annual_value_low_m,annual_value_high_m,complexity,time_to_value_low_mo,time_to_value_high_mo,data_sources,value_components,key_assumptions,roi_timeline,prerequisites) VALUES ('63b20632-d980-49a0-9f67-e4c079f728c6','Voltage Optimization & Loss Reduction','Distribution','Phase 2','Backlog','Technical losses run ~5% of 5,000 MW system load; voltage violations and reactive-power costs are addressable but unmanaged.','Optimize volt/VAR settings across the distribution network using AMI voltage data and capacitor/regulator telemetry. Enables conservation voltage reduction (CVR).','Optimization','Distribution Operations','Distribution',NULL,NULL,NULL,NULL,NULL,18,38,3,12,18,'AMI voltage data, SCADA, capacitor bank status, regulator settings, feeder models','Energy loss reduction 1-3% ($7.5M); VAR cost reduction ($2M); Voltage violation reduction ($1M); Equipment life extension ($1.05M); CVR ($10M)','5,000 MW avg system load; 5% technical losses (250 MW); CVR factor 0.7; voltage cut 1.5% within limits','12-18 months','Clean AMI voltage data; volt/VAR device telemetry');
INSERT INTO use_cases (id,title,category,phase,status,business_problem,solution_description,ai_capability,business_area,value_stream,executive_sponsor,funding_status,risks,requestor_name,planview_tracking_number,annual_value_low_m,annual_value_high_m,complexity,time_to_value_low_mo,time_to_value_high_mo,data_sources,value_components,key_assumptions,roi_timeline,prerequisites) VALUES ('7a9a8110-2975-409d-9f59-e6955006160f','Hosting Capacity Analysis','Distribution','Phase 2','Backlog','DER interconnection cycle time is 3-6 months; engineering studies are a bottleneck.','Quantify where the grid can accept new DERs without upgrades. Feeder-by-feeder hosting capacity maps cut interconnection studies to 2-4 weeks.','Optimization','DER Interconnection','Distribution',NULL,NULL,NULL,NULL,NULL,15,32,4,12,18,'Feeder models, AMI, DER interconnection data, load forecasts, protection settings, thermal limits','Interconnection study cost reduction ($2M); Faster approvals revenue ($5M); Infra deferral via optimal siting ($3.5M); Feeder upgrade avoidance ($20M); Regulatory compliance ($2M)','500 DER applications/yr +20%/yr; cycle time 3-6 months -> 2-4 weeks; 10 feeder upgrades/yr deferrable','12-18 months','Load Forecasting at Feeder Level');
INSERT INTO use_cases (id,title,category,phase,status,business_problem,solution_description,ai_capability,business_area,value_stream,executive_sponsor,funding_status,risks,requestor_name,planview_tracking_number,annual_value_low_m,annual_value_high_m,complexity,time_to_value_low_mo,time_to_value_high_mo,data_sources,value_components,key_assumptions,roi_timeline,prerequisites) VALUES ('af8fd72f-523d-4a06-9f61-90c37e1d9ac7','Distribution Network Digital Twin','Distribution','Phase 3','Backlog','No simulation environment to test switching, DER scenarios, or planning decisions before they hit the live grid.','Full distribution digital twin combining AMI, SCADA, GIS, DER telemetry, weather, and real-time switching state. Enables operational simulation, planning, and real-time optimization.','Optimization','Distribution Engineering','Distribution',NULL,NULL,NULL,NULL,NULL,35,72,5,48,60,'AMI, SCADA, GIS, DER telemetry, weather, real-time switching state, customer data','SAIDI reduction via twin automation ($30M); Planning cost reduction ($8M); Switching optimization ($4M); Energy loss reduction ($876K); DER hosting value ($10M)','4+ years of Phase 1-2 data; clean GIS model; +15 SAIDI min eliminated beyond Phase 1-2; 100K switching ops/yr','48-60 months','All Phase 1-2 distribution data; clean GIS model');
INSERT INTO use_cases (id,title,category,phase,status,business_problem,solution_description,ai_capability,business_area,value_stream,executive_sponsor,funding_status,risks,requestor_name,planview_tracking_number,annual_value_low_m,annual_value_high_m,complexity,time_to_value_low_mo,time_to_value_high_mo,data_sources,value_components,key_assumptions,roi_timeline,prerequisites) VALUES ('edcbaba0-f182-4186-a482-ab23abe16f21','Automated Work Package Generation for Crews','Distribution','Phase 3','Backlog','200 planners spend 50% of their time manually assembling work packages; 5,000 jobs/yr are delayed by gaps.','AI assembles complete work packages (instructions, materials, permits, safety plans) from work orders, GIS, asset condition, crew skills, and material availability.','Generative AI / Agents','Work Management','Distribution',NULL,NULL,NULL,NULL,NULL,18,38,4,36,48,'Work orders, GIS, asset condition, crew skills/certifications, material availability, schedules','Planning labor savings ($17M); Crew productivity ($5.3M); Permit cycle time reduction ($2M); Safety plan quality ($1.5M); Material availability ($4.5M)','200 planners at 50% on manual package assembly; 5,000 field crews x 30 min/day pre-job prep; 5,000 jobs/yr delayed','36-48 months','Mature work-management data; integrated material/skills systems');
INSERT INTO use_cases (id,title,category,phase,status,business_problem,solution_description,ai_capability,business_area,value_stream,executive_sponsor,funding_status,risks,requestor_name,planview_tracking_number,annual_value_low_m,annual_value_high_m,complexity,time_to_value_low_mo,time_to_value_high_mo,data_sources,value_components,key_assumptions,roi_timeline,prerequisites) VALUES ('deef23a4-d49e-4f7f-8883-0a60e1268209','Automated Work Order Creation & Crew Dispatching','Distribution','Phase 3','Backlog','50 dispatchers spend 37% of their time on manual work order creation; crew utilization and overtime remain stubbornly suboptimal.','Close the loop from fault detection through automated dispatch using OMS, the digital twin, crew locations, and priority models.','Generative AI / Agents','Dispatch Operations','Distribution',NULL,NULL,NULL,NULL,NULL,25,52,5,48,60,'OMS, digital twin, crew locations, skills, equipment, traffic, priority models','SAIDI reduction faster dispatch ($10M); Dispatcher efficiency ($3.19M); Crew utilization ($8.5M); Overtime reduction ($4.5M); Mutual aid coordination ($10M)','Validated digital twin; 50 dispatchers at 37% manual time; 5,000 field crews; $30M annual distribution crew overtime','48-60 months','Distribution Network Digital Twin');
INSERT INTO use_cases (id,title,category,phase,status,business_problem,solution_description,ai_capability,business_area,value_stream,executive_sponsor,funding_status,risks,requestor_name,planview_tracking_number,annual_value_low_m,annual_value_high_m,complexity,time_to_value_low_mo,time_to_value_high_mo,data_sources,value_components,key_assumptions,roi_timeline,prerequisites) VALUES ('512e2189-2fcc-425e-b516-638308ae6066','Self-healing Distribution Networks','Distribution','Phase 3','Backlog','Sustained outages still drive SAIDI minutes that customers and regulators no longer accept.','Ultimate distribution automation: the network detects, isolates, and restores faults autonomously by orchestrating FLISR, DERs, switching, and protection.','Optimization','Distribution Operations','Distribution',NULL,NULL,NULL,NULL,NULL,45,92,5,60,72,'Digital twin, FLISR automation, DER orchestration, real-time switching, protection coordination','SAIDI elimination ($40M); Crew overtime reduction ($9M); Regulatory performance ($5M); CSAT premium ($5M); Capital deferral ($3.5M)','Requires digital twin, automated dispatch, FLISR foundation; self-healing handles 60% of fault events; cumulative SAIDI reduction across Phase 3: 40+ min','60-72 months','Distribution Network Digital Twin; Automated Work Order Creation; FLISR');
INSERT INTO use_cases (id,title,category,phase,status,business_problem,solution_description,ai_capability,business_area,value_stream,executive_sponsor,funding_status,risks,requestor_name,planview_tracking_number,annual_value_low_m,annual_value_high_m,complexity,time_to_value_low_mo,time_to_value_high_mo,data_sources,value_components,key_assumptions,roi_timeline,prerequisites) VALUES ('64d5e54d-33ab-4857-8652-5783148e7612','Hyper-local Probabilistic Risk Pricing','Distribution','Phase 3','Backlog','$300M annual distribution capital is allocated with limited asset-level risk insight; 5 high-consequence failures per year are currently preventable.','Price risk at the individual asset/segment level using probabilistic failure and consequence models. Enables surgical investment decisions and insurance optimization.','Predictive Maintenance','Asset Management','Distribution',NULL,NULL,NULL,NULL,NULL,20,42,4,48,60,'Asset condition, weather exposure, vegetation, customer density, failure probability, consequence models','Capital investment precision ($9M); Insurance optimization ($4M); Regulatory capital justification ($600K); Catastrophic failure prevention ($10M); Litigation avoidance ($3M)','$300M annual distribution capital; 3% allocation improvement; 5 high-consequence failures/yr preventable; 3 litigation cases/yr at $1M avg','48-60 months','Predictive Maintenance baseline; asset condition data integrated');
